import { showModal } from '@ui-kit/Modal';

import HikingRepairKitUsageModal from './HikingRepairKitUsageModal';
import { IHikingData } from '../../../@types/hiking.types';
import { IHikingRepairKit, IHikingRepairKitUsage } from '../../../@types/hikingRepairKit.types';

interface IAddRepairKitUsageInModalProps {
  hikingData: IHikingData;
  repairKit: IHikingRepairKit;
  repairKitUsage: IHikingRepairKitUsage;
}

export const addRepairKitUsageInModal = (
  props: IAddRepairKitUsageInModalProps,
): Promise<IHikingRepairKitUsage> => {
  return new Promise((res) => {
    showModal({
      title: props.repairKit.name + '. Добавление использования',
      flushBody: true,
      children: (clos: any) => (
        <HikingRepairKitUsageModal
          hikingData={props.hikingData}
          repairKitUsage={props.repairKitUsage}
          onChange={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
