import React, { FormEvent } from 'react';

import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';

import HikerSelectInput from '../../../@components/HikerSelectInput';
import { mapHikerToUser, mapUserToHiker } from '../../../@mappers/hiking.mapper';
import {
  addHikingRepairKitItem,
  updateHikingRepairKitItem,
} from '../../../@services/hikingRepairKit.service';
import {
  IHikingRepairKitCreateDTO,
  IHikingRepairKitUpdateDTO,
} from '../../../@types/DTO/hikingRepairKit.dto.types';
import { IHikingData } from '../../../@types/hiking.types';
import { IHikingRepairKit } from '../../../@types/hikingRepairKit.types';

interface IHikingRepairKitModalProps {
  hikingData: IHikingData;
  repairKit: IHikingRepairKit;
  onChange: (rk: IHikingRepairKit) => void;
}

const HikingRepairKitModal: React.FC<IHikingRepairKitModalProps> = ({
  repairKit,
  hikingData,
  onChange,
}) => {
  const [data, setData] = React.useState<IHikingRepairKit>(repairKit);
  const [isLoading, setIsLoading] = React.useState(false);

  type T = Omit<IHikingRepairKit, 'id' | 'id_hiking'>;

  const handleInputChange =
    <K extends keyof T>(field: keyof T) =>
    async (value: T[K]) => {
      setData((cur) => ({ ...cur, [field]: value }));
    };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsLoading(true);
      const dataForSave: IHikingRepairKitCreateDTO = {
        id_hiking: hikingData.id,
        name: data.name,
        comment: data.comment,
        weight: data.weight,
        id_assignee: data.assignee ? data.assignee.id : null,
      };
      if (data.id > 0) {
        const dataForAdd: IHikingRepairKitUpdateDTO = {
          ...dataForSave,
          id: data.id,
        };
        await updateHikingRepairKitItem(dataForAdd);
        onChange(data);
        notificationHelper.success('Сохранено');
      } else {
        const newId = await addHikingRepairKitItem(dataForSave);
        onChange({ ...data, id: newId });
        notificationHelper.success('Добавлено');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ minWidth: 360 }}>
      <PohInput
        label="Название"
        placeholder="Элемент ремнабора"
        name="hiking-repair-kit-name"
        id="hiking-repair-kit-name"
        required
        value={data.name}
        onChange={handleInputChange<'name'>('name')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />
      <PohInput
        label="Вес (грамм)"
        name="hiking-repair-kit-weight"
        id="hiking-repair-kit-weight"
        required
        value={data.weight.toString()}
        type={InputTypes.number}
        min={1}
        step={1}
        max={99999}
        onChange={(v) => handleInputChange<'weight'>('weight')(+v)}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />
      <PohInput
        type={InputTypes.textarea}
        label="Комментарий"
        placeholder="Например: Кол-во, Зачем нужно итп"
        name="hiking-repair-kit-comment"
        id="hiking-repair-kit-comment"
        value={data.comment}
        onChange={handleInputChange<'comment'>('comment')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />

      <div className="mb-2 d-flex align-items-center">
        <HikerSelectInput
          id_hiking={hikingData.id}
          value={data.assignee ? mapUserToHiker(data.assignee) : null}
          onChange={(hiker) => handleInputChange<'assignee'>('assignee')(mapHikerToUser(hiker))}
          label={'Ответственный/У кого'}
          placeholder="Не заполнять если у реммастера"
          wrapperClassName="flex-grow-1"
        />
        {data.assignee && (
          <PohButton
            icon={IconsEnum.close}
            onClick={() => handleInputChange<'assignee'>('assignee')(null)}
          />
        )}
      </div>

      <footer className="pt-3 text-end">
        <PohButton
          variant={ButtonVariant.Primary}
          size={ButtonSize.Small}
          type="submit"
          disabled={isLoading}
        >
          {data.id ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default HikingRepairKitModal;
