import { showModal } from '@ui-kit/Modal';

import HikingRepairKitModal from './HikingRepairKitModal';
import { IHikingData } from '../../../@types/hiking.types';
import { IHikingRepairKit } from '../../../@types/hikingRepairKit.types';

interface IAddOrEditRepairKitItemInModalProps {
  hikingData: IHikingData;
  repairKit: IHikingRepairKit;
}

export const addOrEditRepairKitItemInModal = (
  props: IAddOrEditRepairKitItemInModalProps,
): Promise<IHikingRepairKit> => {
  return new Promise((res) => {
    showModal({
      title: props.repairKit.id ? 'Редактирование ремнабора' : 'Добавление в ремнабор',
      flushBody: true,
      children: (clos: any) => (
        <HikingRepairKitModal
          hikingData={props.hikingData}
          repairKit={props.repairKit}
          onChange={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
