import React from 'react';

import { useNavigate } from 'react-router-dom';

import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohContainer from '@ui-kit/layout/Container';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { addOrEditRepairKitItemInModal } from './components/HikingRepairKitModal';
import { addRepairKitUsageInModal } from './components/HikingRepairKitUsageModal';
import { AuthContext } from '../../../contexts/AuthContext';
import { getHikingDataAsync } from '../@services/hiking.service';
import {
  deleteHikingRepairKitItem,
  deleteHikingRepairKitUsages,
  getHikingRepairKitItems,
  getHikingRepairKitUsages,
} from '../@services/hikingRepairKit.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingRepairKit, IHikingRepairKitUsage } from '../@types/hikingRepairKit.types';
import HikingApproves from '../approves/HikingApproves';

const HikingRepairKitPage: React.FC<{ id_hiking: number }> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [repairKitItems, setHikingRepairKitItems] = React.useState<IHikingRepairKit[] | null>(null);
  const [repairKitUsages, setHikingRepairKitUsages] = React.useState<IHikingRepairKitUsage[]>([]);
  const [canEdit, setCanEdit] = React.useState(false);
  const authContext = React.useContext(AuthContext);

  const navigate = useNavigate();

  React.useEffect(() => {
    getHikingDataAsync(id_hiking).then(setHikingData);
    getHikingRepairKitItems(id_hiking).then(setHikingRepairKitItems);
    getHikingRepairKitUsages(id_hiking).then(setHikingRepairKitUsages);
    getHikingAccessGroupAsync(id_hiking).then((accessGroup) => {
      setCanEdit(
        [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Equip,
        ].includes(accessGroup),
      );
    });
  }, [id_hiking]);

  if (hikingData == null || repairKitItems == null) {
    return <PageLoader />;
  }

  const handleAdd = async () => {
    if (!authContext.user?.id) return;
    const newItem = await addOrEditRepairKitItemInModal({
      hikingData,
      repairKit: {
        id: 0,
        name: '',
        comment: '',
        create: {
          date: new Date(),
          user: authContext.user,
        },
        weight: 23,
        assignee: null,
        update: null,
      },
    });
    setHikingRepairKitItems((cur) => [...(cur ?? []), newItem]);
  };

  const handleEdit = async (repairKit: IHikingRepairKit) => {
    if (!authContext.user?.id) return;
    const updatedItem = await addOrEditRepairKitItemInModal({ hikingData, repairKit });
    setHikingRepairKitItems((cur) =>
      (cur ?? [])?.map((i) => (i.id === repairKit.id ? updatedItem : i)),
    );
  };

  const handleDelete = async (repairKit: IHikingRepairKit) => {
    if (!authContext.user?.id) return;
    if (!(await confirmModal2(`Удалить "${repairKit.name}"?`))) return;
    await deleteHikingRepairKitItem({ id_hiking: hikingData.id, id: repairKit.id });
    setHikingRepairKitItems((cur) => (cur ?? [])?.filter((i) => i.id !== repairKit.id));
    notificationHelper.success('Удалено!');
  };

  const handleAddUsage = async (repairKit: IHikingRepairKit) => {
    if (!authContext.user?.id) return;
    const newItem = await addRepairKitUsageInModal({
      hikingData,
      repairKit,
      repairKitUsage: {
        id: 0,
        id_hiking_repair_kit: repairKit.id,
        date: new Date(),
        comment: '',
        create: {
          date: new Date(),
          user: authContext.user,
        },
        user: null,
      },
    });
    setHikingRepairKitUsages((cur) => [...(cur ?? []), newItem]);
  };

  const handleDeleteUsage = async (usage: IHikingRepairKitUsage) => {
    if (!authContext.user?.id) return;
    if (!(await confirmModal2(`Удалить использование "${usage.date.toLocaleString()}"?`))) return;
    await deleteHikingRepairKitUsages({ id_hiking: hikingData.id, id: usage.id });
    setHikingRepairKitUsages((cur) => (cur ?? [])?.filter((i) => i.id !== usage.id));
    notificationHelper.success('Удалено!');
  };

  const usagesMap = repairKitUsages.reduce<Record<number, IHikingRepairKitUsage[]>>((acc, cur) => {
    if (!acc[cur.id_hiking_repair_kit]) acc[cur.id_hiking_repair_kit] = [];
    acc[cur.id_hiking_repair_kit].push(cur);
    return acc;
  }, {});

  return (
    <div>
      <div className="d-print-none">
        <PohBreadcrumbs
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/repair-kit`, text: 'Ремнабор', active: true },
          ]}
        />
      </div>

      <PohContainer>
        <header className="d-flex align-items-center justify-content-between">
          <h3>Ремнабор похода &laquo;{hikingData.name}&raquo;</h3>
          <aside className="d-print-none">
            <PohButton
              size={ButtonSize.Small}
              onClick={() => navigate(`/hiking/${id_hiking}/repair-kit/print`)}
            >
              Печать
            </PohButton>
            {canEdit && (
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.Success}
                onClick={handleAdd}
                className="ms-2"
              >
                Добавить
              </PohButton>
            )}
          </aside>
        </header>
        {repairKitItems.length === 0 ? (
          <Empty>Ремнабор не настроен</Empty>
        ) : (
          <table className="table table-sm table-condensed table-bordered">
            <thead>
              <tr>
                <th>Название</th>
                <th>Вес (г)</th>
                <th>Комментарий</th>
                <th>У кого</th>
                <th>Использование</th>
                {canEdit && <th className="d-print-none">&nbsp;</th>}
              </tr>
            </thead>
            <tbody>
              {repairKitItems.map((m) => (
                <tr key={m.id}>
                  <td>{m.name}</td>
                  <td className="text-end">{m.weight}</td>
                  <td style={{ whiteSpace: 'pre-wrap' }}>{m.comment}</td>
                  <td>{m.assignee ? [m.assignee.name, m.assignee.surname].join(' ') : '–'}</td>
                  <td>
                    {usagesMap[m.id] && usagesMap[m.id].length > 0 ? (
                      <ol>
                        {usagesMap[m.id].map((li) => {
                          return (
                            <li key={li.id} className="m-0">
                              <small className="text-info me-1">{li.date.toLocaleString()}.</small>
                              {li.user && (
                                <span>
                                  {li.user?.name ?? ''} {li.user?.surname ?? ''}.
                                </span>
                              )}
                              <em className="ms-1">{li.comment}.</em>
                              {canEdit && (
                                <PohButton
                                  size={ButtonSize.Small}
                                  onClick={() => handleDeleteUsage(li)}
                                  icon={IconsEnum.trash}
                                />
                              )}
                            </li>
                          );
                        })}
                      </ol>
                    ) : canEdit ? (
                      <></>
                    ) : (
                      '–'
                    )}
                    {canEdit && (
                      <footer>
                        <PohButton size={ButtonSize.Small} onClick={() => handleAddUsage(m)}>
                          Добавить использование
                        </PohButton>
                      </footer>
                    )}
                  </td>
                  {canEdit && (
                    <td align="right" className="d-print-none">
                      <PohButton
                        icon={IconsEnum.edit}
                        onClick={() => handleEdit(m)}
                        variant={ButtonVariant.Light}
                        size={ButtonSize.Small}
                      />
                      <PohButton
                        icon={IconsEnum.trash}
                        onClick={() => handleDelete(m)}
                        variant={ButtonVariant.Light}
                        size={ButtonSize.Small}
                      />
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr>
                <td className="text-end text-muted">Итого:</td>
                <td className="text-end text-muted">
                  {repairKitItems.reduce((sum, item) => sum + item.weight, 0)}&thinsp;г.
                </td>
                <td className="text-end text-muted">{repairKitItems.length}шт</td>
                <td></td>
                <td></td>
                <td className="d-print-none">&nbsp;</td>
              </tr>
            </tfoot>
          </table>
        )}
        <HikingApproves hikingData={hikingData} entity_type="repair_kit" />
      </PohContainer>
    </div>
  );
};

export default HikingRepairKitPage;
